VALUES(md5('facodi:ualg:1929:course:record')::uuid,md5('facodi:ualg:1929:course')::uuid,'CTESP-MD','ualg_official','1929','ctesp-marketing-digital',
 'CTeSP em Marketing Digital','Marketing Digital','Curso Técnico Superior Profissional da Universidade do Algarve, na Escola Superior de Gestão, Hotelaria e Turismo, em Faro, com 120 ECTS em quatro semestres. Escrita para a web, marketing de conteúdos, SEO e publicidade nos motores de pesquisa, redes sociais, email marketing, comércio eletrónico e web analytics, com estágio de 30 ECTS.','<h2>Apresentação</h2><p>O CTeSP em Marketing Digital funciona em Faro, no Campus da Penha, e forma técnicos superiores profissionais para gerir a presença digital de uma organização: criar e adaptar conteúdos, dinamizar redes sociais, apoiar campanhas de publicidade online, SEO, email e mobile marketing, colaborar em projetos de comércio eletrónico e acompanhar resultados com métricas digitais.</p><h2>Plano de estudos</h2><p>18 unidades curriculares de 5 ECTS nos três primeiros semestres e um estágio de 30 ECTS no quarto. O 1.º ano junta as bases (marketing, gestão, informática, tecnologias web, inglês técnico, escrita para a web) às ferramentas de pesquisa, conteúdos, design e multimédia; o 3.º semestre trata comércio eletrónico, redes sociais, email e mobile marketing, métodos quantitativos, web analytics e o plano de marketing digital.</p><h2>Na FACODI</h2><p>Cada unidade curricular tem playlists abertas do YouTube escolhidas a partir do programa da ficha oficial da UC.</p>',
 'CTeSP','pt','Escola Superior de Gestão, Hotelaria e Turismo','https://www.ualg.pt/curso/1929','https://www.ualg.pt/curso/1929/plano','active',true,
 jsonb_build_object('level','CTeSP (nível 5)','campus','Faro','official_course_id','1929','official_academic_year','2026/27',
 'official_plan_url','https://www.ualg.pt/curso/1929/plano','official_source','https://www.ualg.pt/curso/1929/plano','official_program_verified',true,'official_ects_total',120,
 'official_unit_count',19,'mandatory_unit_count',19,'official_semester_count',4,'curriculum_is_ctesp_not_licenciatura',true,
 'curriculum_contains_elective_alternatives',false,
 'separate_offerings',jsonb_build_array('Marketing Digital - Portimão (plano próprio)'),
 'source_quality','ualg_official_programme','curriculum_review_status','approved_official_plan','curation_batch','facodi_ualg_1929_ctesp_marketing_digital_20261118'),
 'Universidade do Algarve',120,4)
ON CONFLICT DO NOTHING;

