SELECT md5('facodi:ualg:1929:uc:'||u.code)::uuid,'curricular_unit',u.title,'facodi-uc-ctesp-marketing-digital-'||u.code,u.summary,'[]'::jsonb,
 u.topics,ARRAY[u.title],'pt','active',true,'import','https://www.ualg.pt/curso/1929/plano','ualg:ctesp:1929:uc:'||u.code,
 jsonb_build_object('university_course_code','1929','unit_code',u.code,'official_academic_year','2026/27',
 'official_fuc_url',u.fuc_url,'detailed_fuc_checked',u.fuc_url IS NOT NULL,'study_topics',to_jsonb(u.topics),'curation_batch','facodi_ualg_1929_ctesp_marketing_digital_20261118')
