 u.code,'ualg_official','1929:'||u.code,
 CASE WHEN EXISTS(SELECT 1 FROM facodi.curricular_units o WHERE o.slug=u.code AND o.course_id<>md5('facodi:ualg:1929:course:record')::uuid)
 THEN 'ctesp-marketing-digital-uc-'||u.code ELSE u.code END,
 u.title,u.title,u.summary,'<p>'||u.summary||'</p><p><strong>Temas:</strong> '||array_to_string(u.topics,'; ')||'.</p>',
 u.year,u.semester,u.ects,u.position,'pt','https://www.ualg.pt/curso/1929/plano','https://www.ualg.pt/curso/1929/plano','active',true,
 jsonb_build_object('course_code','CTESP-MD','official_course_id','1929','official_unit_code',u.code,'academic_year','2026/27',
 'official_academic_year','2026/27','official_plan_url','https://www.ualg.pt/curso/1929/plano','official_fuc_url',u.fuc_url,'detailed_fuc_checked',u.fuc_url IS NOT NULL,
 'official_code_checked',true,'official_ects_checked',true,'official_semester_checked',true,'local_semester',u.local_semester,
 'offered_in_both_semesters',u.offered_both_terms,'is_elective_option',u.option_group IS NOT NULL,'official_option_group',u.option_group,
 'curriculum_placements',u.placements,'study_topics',to_jsonb(u.topics),'source_quality','ualg_official_structure',
 'curriculum_review_status','approved_official_plan','curation_batch','facodi_ualg_1929_ctesp_marketing_digital_20261118')
FROM _u u
ON CONFLICT DO NOTHING;

INSERT INTO facodi.learning_object_relations(id,parent_object_id,child_object_id,relation_type,position,created_by_mechanism,metadata)
SELECT md5('facodi:ualg:1929:course-uc-link:'||u.code)::uuid,md5('facodi:ualg:1929:course')::uuid,md5('facodi:ualg:1929:uc:'||u.code)::uuid,
